      {h:"エレンの原体験", body:"エレンは倒壊した家屋に挟まれた母カルラを助け出せず、目の前で巨人に捕食される。ハンネスが二人を担いで逃げたことで生き延び、以後「巨人の駆逐」が行動原理になる。"},
      {h:"人類側の被害", body:"ウォール・マリアは放棄され、人類の活動領域はウォール・ローゼまで後退。全人口の2割と領土の1/5を失った。"},
      {h:"翌年の領土奪還作戦", body:"難民の口減らしを兼ねた奪還作戦が846年に敢行され、送り込まれた約20万人のうち生還者はごくわずか。アルミンは家族をここで失う。人類が巨人を数で押せないと確定した戦い。"},
      {h:"あとから分かること", body:"超大型はベルトルト、鎧はライナー、そしてこの日の混乱に紛れて顎のマルセルがユミルの民に喰われている。同じ日、グリシャはエレンに巨人化の注射を打ち、始祖と進撃の巨人を継承させていた。"}
