      {h:"大岩作戦", body:"巨人化したエレンが大岩を運んで破られた扉を塞ぐ、というアルミン発案の作戦。一度は暴走してミカサに殴りかかったが、アルミンの呼びかけで正気を取り戻し岩を運びきった。"},
      {h:"結果", body:"人類は初めて巨人から領地を奪還した。同時に104期には多数の死者が出て、マルコの遺体を見たジャンは調査兵団志望に転じる。エレンは調査兵団の特別作戦班へ配属される。"}
