      {h:"手口", body:"ザックレー総統を爆弾で暗殺し、反対派の兵士や義勇兵を拘束、ワインに脊髄液を混ぜて有力者を人質化した。ヒストリア女王も事実上の傀儡になる。"},
      {h:"末路", body:"地鳴らし発動後、エレンを止めようとする混成部隊とオニャンコポンらを敵に回す。フロックは飛行艇の離陸を止めようとしてガビに射たれ、水路に落ちて死んだ。"},
      {h:"読みどころ", body:"「自由のために戦ってきた側」が、自由の名で人を縛る組織に変わる過程。エルヴィンの死が別の人間に別の意味で受け継がれた結果でもある。"}
