      {h:"叫び", body:"王家の血を引くジークが継承したことで、脊髄液を摂取した者を任意に巨人化させ、無垢の巨人を意のままに操れた。ラガコ村の一斉巨人化がその実例。"},
      {h:"継承者", body:"トム・クサヴァー → ジーク・イェーガー。クサヴァーはジークに「安楽死計画」を授けた人物でもある。"}
