      {h:"継承者", body:"マルセル・ガリアード → ユミル（無垢の巨人時代に喰う） → ポルコ・ガリアード → ファルコ・グライス。兄マルセルの力が弟ポルコに戻り、さらに次の子に渡るという皮肉な流れ。"},
      {h:"ユミルの60年", body:"ユミルは幼少期に無垢の巨人にされ、60年ものあいだ壁外を彷徨った末にマルセルを喰って人に戻った。この一口が、ライナーたちの作戦を歪めた最初の分岐だった。"}
