      {h:"継承者", body:"ラーラ・タイバー → エレン・イェーガー。タイバー家が代々秘匿しており、マーレ軍にも自由に使わせなかった。"},
      {h:"攻略", body:"エレンは地中のケーブルを追い、ミカサの助けで本体の結晶を掘り出して捕食した。以後エレンは三つの巨人（始祖・進撃・戦鎚）を持つ。"}
