    summary:"安全な内地を目指していた少年が、いちばん現実的な指揮官になった。",
    detail:[
      {h:"人物", body:"トロスト区出身。104期6位。立体機動の扱いに長け、状況を冷静に読む力がある。当初は憲兵団志望で、理由は「安全だから」と隠さなかった。"},
      {h:"転機", body:"トロスト区でマルコを失い、その遺体を確認したことで調査兵団を志願する。「理想の指揮官」と慕っていた相手の資質を、自分が引き受ける決断だった。"},
      {h:"役割", body:"エレンの替え玉、王政編での対人戦、シガンシナ、レベリオ、そして地鳴らし阻止。物語の後半は「エレンでもアルミンでもない普通の兵士の視点」を担い続ける。"},
      {h:"人を殺すこと", body:"王政編で人を撃ち、レベリオでは一般市民のいる場所での戦闘に加担した。そのつらさを最後まで言葉にできる数少ない人物。"},
      {h:"その後", body:"存命。エレンを止める側に立ち、最後まで生き残った。"},
      {h:"人物像", body:"エレンと反発し合うが、根っこの現実感覚が最も高い。皮肉屋のわりに、いつも一番人間らしい判断を出す。"}
    ],
