      {h:"故郷", body:"ウォール・ローゼ侵入事件で戻った村は無人で、家々が内側から壊されていた。取り残された巨人に母の面影を見つける。後にジークの叫びで村人全員が巨人化させられたと判明する。"},
      {h:"最大の分岐", body:"母を人間に戻すため、巨人化したファルコを母に喰わせようとした。ガビとの取っ組み合いとファルコ自身の言葉で我に返り、思いとどまる。"},
      {h:"役割", body:"サシャの死後は104期の最年少組の面倒を見る側になり、ガビとファルコを受け入れる過程を担う。"},
      {h:"その後", body:"存命。巨人の力の消滅で、ラガコ村の住人も母も人間に戻った。"}
