      {h:"背景", body:"故郷の言葉遣いを恥じて敬語で話していた過去がある。父アルトゥルとの関係と、狩人としての生き方が後の性格の芯になっている。"},
      {h:"活躍", body:"ウォール・ローゼ侵入時にダウパー村でカヤを救い、以後カヤはブラウス家に引き取られた。シガンシナ、レベリオでも狙撃と索敵で貢献する。"},
      {h:"最期", body:"レベリオからの撤退中、飛行船に潜り込んだガビに撃たれて死亡。仲間に囲まれながら最後に発した言葉は「肉」だった。"},
      {h:"影響", body:"この死が島の空気を決定的に硬化させ、ガビ自身を作品の最も重い当事者にした。ニコロやカヤの怒りも、ここから動く。"}
