      {h:"言葉", body:"キースに向けて語った「あの子は偉くなんてなくていい、私はエレンが生まれてくれただけでいい」という言葉が、後にキースとエレンの両方を縛る。エレンの人生の全体に対する反論として置かれている。"},
      {h:"最期", body:"845年、倒壊した家に脚を挟まれて動けず、エレンとミカサを逃がすために「二人を連れて逃げて」とハンネスに頼んだ。目の前で巨人（ダイナ・フリッツの巨人体）に喰われた。"},
      {h:"最後の言葉", body:"回想が繰り返されるたびに描写が変わり、最終的には「行かないで」と叫んでいたことが明らかになる。エレンが記憶を都合よく整えていたことの証でもある。"}
