      {h:"告発", body:"自分と祖父母に危険が及ぶと知った息子ジークがマーレ当局に告発し、グリシャらとともに捕らえられる。グリシャは王家の末裔と分かれば助かると考えて素性を明かしたが、尋問官のクルーガーは「生涯を始祖の器として生かされる」ことのほうが残酷だと判断し、彼女を無垢の巨人にした。"},
      {h:"作中の役", body:"無垢の巨人として長年パラディ島を彷徨い、845年に壁内へ侵入してカルラを喰う。奪還戦ではハンネスも喰った。"},
      {h:"最期", body:"動けないエレンが彼女の巨人体に触れた瞬間、座標の力が発動して周囲の巨人が殺到し、ライナーとベルトルトに向かって食い散らかされて死亡した。"},
      {h:"読みどころ", body:"「母を殺した巨人」が「異母兄の母」であり「王家の最後の血」だった、という一点に作品の構造が全部詰まっている。"}
