      {h:"継承", body:"15歳のとき、叔父ウーリから始祖の巨人と「世界の記憶」を継承。継承前は「先祖の亡霊には負けない」と抵抗の意思を示していたが、初代レイス王の不戦の契りに支配され、歴代と同じ道を選んだ。"},
      {h:"ヒストリアとの関係", body:"幼いヒストリアに親身に接し続けたが、別れの際に始祖の力で記憶を封じたため、ヒストリアは長年その存在を認識できずにいた。疎外されて育った彼女にとって唯一の愛情だった。"},
      {h:"最期", body:"845年、ウォール・マリア陥落と同じ日にグリシャとの戦いに敗れ、喰われて死亡。エレンの中にフラッシュバックしていた黒髪の女性の記憶は、グリシャを経由したフリーダの記憶だった。"}
