      {h:"何もしなかった王", body:"かつては兄と共に巨人の駆逐を望んでいたが、記憶の継承後は不戦の契りに支配され、世を深く憂いながら行動を起こさなかった。"},
      {h:"ケニー", body:"王政への反逆者だったケニーを中央憲兵に登用した張本人。世界を統べる立場でありながら寛容で謙虚な精神性は、ケニーの人生に決定的な影響を与えた。"}
