      {h:"人物", body:"851年の第一次調査船団の一員としてパラディ島に上陸し、ハンジとリヴァイに捕らえられた元マーレ兵。料理の腕を買われ、104期にマーレ料理を振る舞ったことで立場を得た。"},
      {h:"サシャ", body:"無心に食べて喜ぶサシャの姿が自分を戦争から救ってくれたと語り、彼女を「大事な人」と呼んだ。カヤからは恋人同士と認識されていた。"},
      {h:"葬儀の夜", body:"サシャに食べさせるはずだった料理をブラウス一家に振る舞った席で、抜け出したガビからサシャ殺害を誇らしげに聞かされて激怒し、ワインボトルで殴りかかった。"},
      {h:"ワインの件", body:"104期と親しかったためイェーガー派と義勇兵に信用されておらず、ジークの脊髄液が仕込まれたワインの真相を知らされていなかった。本人は気づいていた。"},
      {h:"その後", body:"存命。軍備増強を掲げる演説に熱狂する群衆を前に、ブラウス一家とともに悲しげな表情を浮かべる姿が最後に描かれる。"}
