      {h:"出自", body:"グリシャと王家の末裔ダイナの子で、エレンの異母兄。王家の血を引くエルディア人。両親の洗脳じみた教育でマーレの戦士を目指すよう育てられたが、本人はそれを望んでいなかった。"},
      {h:"告発", body:"期待に応えられない自分と祖父母の身を守るため、両親と復権派をマーレ当局に告発した。この選択が彼の人生の芯にあり続ける。父の代わりに彼を認めたのは、先代の獣の巨人トム・クサヴァーだった。"},
      {h:"安楽死計画", body:"クサヴァーと築いた構想。始祖の力でユミルの民から生殖能力を奪い、巨人の力とエルディア人を一世代で穏やかに終わらせる。「生まれてこないほうがよかった」を出発点にした答え。"},
      {h:"誰と戦ったか", body:"ラガコ村の村人を巨人化させ、ウォール・ローゼでミケを殺し、シガンシナで投石によって調査兵団を壊滅させた。リヴァイに引き剥がされて一度は死んだように見せ、実際は別の巨人に移って生き延びた。"},
      {h:"道での結末", body:"エレンに計画を拒まれ、始祖ユミルも味方につけられない。アルミンとの対話で「無意味に思えた人生にも、何かを愛した時間があった」と気づき、地鳴らしを止めるために投降した。"},
      {h:"最期", body:"エレンに首を刎ねられて死亡。歴代の九つの巨人を説得し、始祖討伐に向かわせた最後の仕事が地鳴らしの停止を可能にした。"},
      {h:"評", body:"作者は「主人公がなってはいけなかった姿」「超えなければいけない兄」としてこのキャラクターを設計したと述べている。"}
