    role:"戦士候補生 → 顎の巨人の継承者", klass:"巨人継承者", first:"23巻", arc:"天と地の戦い", status:"存命",
    tags:["顎の巨人","飛行","ガビ","エレンとの文通","ブラウス家"],
    summary:"ガビを守るために巨人になろうとした少年。翼を得て地鳴らしを止めた。",
    detail:[
      {h:"人物", body:"戦士候補生。ガビに好意を寄せ、彼女を戦士にしないために自分が鎧の巨人を継ごうとしていた。ガビとは対照的に、パラディ島の住民も自分たちと変わらない人間だと考えていた。"},
      {h:"エレンとの縁", body:"レベリオで負傷兵に扮したエレンと親しくなり、手紙の代筆をしていた。相手がエレンだと気づかないまま工作に利用されていたが、その交流自体はエレンにとっても本物だった。"},
      {h:"巨人化", body:"ブラウス厩舎で、激怒したニコロがガビに殴りかかった際に庇い、ワインに仕込まれたジークの脊髄液を摂取してしまう。港の戦いでジークの叫びによって無垢の巨人になった。"},
      {h:"継承", body:"ポルコが自ら喰われる形で顎の巨人を継がせ、人間に戻る。ジークの脊髄液の影響で獣の巨人の特徴がわずかに出ており、後に飛行能力を獲得した。"},
      {h:"活躍", body:"飛べる顎の巨人として、ミカサやアルミンを運びながら地鳴らしを止める作戦の主力になった。"},
      {h:"その後", body:"存命。最終回ではリヴァイ、ガビ、オニャンコポンとともに行動しており、アニメ版ではガビと地鳴らしで壊れた森の再生に携わっている。"}
    ],
