      {h:"憂い", body:"巨人の力の限界と、軍国主義の暴走でマーレが自壊することを見越しており、マーレ人の徴兵制の復活を働きかけていた。"},
      {h:"元帥", body:"レベリオでエレンが軍上層部を全滅させたため臨時の元帥を代行。ライナーのパラディ島奇襲案を採用し、人材不足のため元帥自ら車力の巨人に載せた対巨人砲の砲手を務めた。"},
      {h:"最期", body:"地鳴らし後は島に取り残され、マーレの巨人を率いてハンジらと共闘してエレンを追う。ハンジたちの輸送船を逃がすため、港に残った軍艦をキース・シャーディスとともに自爆させて死んだ。その直前、内心では候補生の子供たちの幸福を願っていたことが描かれる。"},
      {h:"読みどころ", body:"「子供に巨人を継がせる制度」の実行者が、最後にその制度の外側で死ぬ。ライナーに「生きろ」と託していったのも彼。"}
