      "上位10名だけが憲兵団を志望できる。安全と出世が「上」にあるという壁内社会の構造がここで説明される。",
      "キース・シャーディスはエルヴィンの前任＝調査兵団第12代団長。エレンを諦めさせようとして、逆に認めた。",
