      {ep:"#32", h:"打・投・極", body:"エレンは格闘技術の差でライナーに完敗する。訓練兵時代にアニから教わった技を思い出して一時は押すが、ベルトルトが超大型として落下してきて戦場が崩壊。エレンとユミルは連れ去られた。"},
      {ep:"#33", h:"追う者", body:"エルヴィンは逃亡先を巨大樹の森と推理し、憲兵団と駐屯兵団も合流して追撃する。追撃中に巨人に腕を噛まれたエルヴィンは、腕を捨てながら「進め」と全軍を鼓舞し続けた。"},
      {ep:"#34", h:"開口", body:"巨大樹の森でユミルが裏の事情を語る。獣の巨人が巨人発生の元凶であり、目的は威力偵察だと指摘する。ライナーとベルトルトは、故郷に帰ればユミルとエレンも救われると信じ込もうとしていた。"},
      {ep:"#35", h:"子供達", body:"ユミルの過去が明かされる。ユミルの民をまとめる少女教の偽の神に仕立てられ、摘発されて楽園送りにされ、60年間巨人として彷徨った末に人に戻った。ヒストリアはユミルに「一緒に生きよう」と告げる。"},
      {ep:"#36", h:"突撃", body:"追撃部隊が到着。巨人を引き連れながらの捨て身の作戦で、ライナーたちの逃走を阻止する。ミカサとリヴァイがエレンの救出に迫り、ベルトルトはエレンを担いだまま身動きが取れなくなる。"},
      {ep:"#37", h:"叫び", body:"ハンネスがエレンを庇って、かつてカルラを喰った巨人に挑み、喰われて死ぬ。何もできず地面を殴ったエレンがその巨人に触れた瞬間、周囲の巨人が一斉にライナーとベルトルトに殺到した。無自覚な「座標」の発動である。エレンは奪回され、ユミルは自ら二人に同行して大陸へ渡った。"}
