      {ep:"#39", h:"痛み", body:"ハンジらは中央憲兵のサネスを捕らえ、拷問して情報を引き出す。相手も洗脳された忠誠でしか動いていないことが分かってくる。人が人を痛めつける側に立つことの重さが、正面から描かれる回。"},
      {ep:"#40", h:"昔話", body:"サネスの自白と回想。エルヴィンの父が壁の歴史に疑問を持ったために殺されていたこと、ヒストリアの母アルマの殺害に関与していたこと、そして真の王家がレイス家であることが明かされる。"},
      {ep:"#41", h:"信頼", body:"リーブス商会のディモが調査兵団側につき、中央憲兵の動きを流す。だがケニーに察知されて殺害され、その罪は調査兵団に着せられた。フレーゲルが父の死の真相を知る。"},
      {ep:"#42", h:"回答", body:"フレーゲルを囮に、街の人々の前で中央憲兵から自白を引き出す作戦が成功する。輿論が動き出す。一方エレンとヒストリアはロッド・レイスの手勢に誘拐された。"},
      {ep:"#43", h:"罪", body:"新生リヴァイ班が編成される。市街地でケニー率いる対人立体機動部隊と交戦。アルミンが初めて人を撃ち、その手の震えを抱えたまま作戦を続ける。ニファらが射殺され、対人戦の速度が巨人戦と違うことが突きつけられる。"},
      {ep:"#44", h:"願い", body:"ヒストリアの過去。私生児として存在を否定され、フリーダにだけ愛情をもらい、その記憶を封じられていた。ロッドは彼女にエレンを喰わせて始祖の巨人を継がせようとする。"},
      {ep:"#45", h:"オルブド区外壁", body:"ヒストリアはエレンの言葉を受け、注射器を叩き割って父を拒む。こぼれた薬液を舐めたロッドは制御不能の巨大な無垢の巨人になり、オルブド区へ向かって這い進み始めた。"},
      {ep:"#46", h:"壁の王", body:"崩落する洞窟でエレンが硬質化を発現し、天井を支えて仲間を救う。ケニーは致命傷を負い、レイス家以外の血統では始祖を継げないと知る。リヴァイに巨人化薬を託して死んだ。"},
      {ep:"#47", h:"友人", body:"オルブド区防衛戦。壁上に火薬を並べてロッド巨人を怯ませ、ヒストリアが父のうなじを斬った。人々の前で「壁の女王」が誕生し、レイス政権は終わる。"},
      {ep:"#48", h:"傍観者", body:"ヒストリアが第18代女王として即位。孤児院の設立や農地の整備といった実務を始める。同時に、壁内で得た硬質化能力を使ってウォール・マリアを奪還する計画が立てられていく。"},
      {ep:"#49", h:"奪還作戦の夜", body:"雷槍の開発、エルヴィンの決意、そして出撃前夜。104期生とリヴァイ、ハンジがそれぞれの覚悟を固める。「地下室に行けば全部分かる」という一点に、全員が賭けることになった。"}
