      {ep:"#51", h:"雷槍", body:"新兵器・雷槍が投入される。エレンとライナーの再戦。硬質化した拳と雷槍でライナーの装甲を破り、うなじを吹き飛ばして一度は仕留めた。だが壁上に上がった兵たちは獣の巨人の投石によって挟撃される。"},
      {ep:"#52", h:"光臨", body:"獣の巨人の投石で調査兵団が壊滅的な損害を受ける。壁上に取り残された兵に逃げ場はない。エルヴィンは新兵を前に、この作戦の意味と自分の私欲を語り始める。"},
      {ep:"#53", h:"完全試合", body:"エルヴィンは新兵に「心臓を捧げよ」と告げ、自ら特攻の先頭に立つ。獣の注意を全部引きつけたその隙に、リヴァイが単騎で樹上から獣の巨人に到達し、ジークを引き剥がして戦闘不能にした。"},
      {ep:"#54", h:"勇者", body:"超大型のベルトルトに対し、アルミンは自らを燃やす捨て身の囮を実行する。エレンが硬質化した拳でベルトルトを引き剥がし、瀕死のアルミンが残された。ミカサとエレンは、リヴァイに「アルミンを助けてくれ」と懇願する。"},
      {ep:"#55", h:"白夜", body:"注射器は一本。エルヴィンを蘇らせて団長として使うか、アルミンを救うか。リヴァイは迷い、最終的に「あんたはもう十分やった」とエルヴィンを休ませ、アルミンにベルトルトを喰わせた。アルミンは超大型巨人を継承して生き延びた。"},
      {ep:"#56", h:"地下室", body:"シガンシナ区は奪還され、穴は塞がれた。だが調査兵団の生存者はごく僅か。ハンジが第14代団長に就く。そしてエレンは、父が「全部分かる」と言い残した家の地下室の鍵を回した。"}
